<?php
if (!defined('ABSPATH')) exit;
function gim_latest_outcome($provider_id,$service){ global $wpdb; return $wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('outcome_runs').' WHERE provider_id=%d AND service_slug=%s ORDER BY id DESC LIMIT 1',$provider_id,$service)); }
function gim_match_providers($job){ global $wpdb; if(!$job||$job->vji_status!=='verified')return []; $providers=$wpdb->get_results('SELECT * FROM '.gim_table('providers')." WHERE status='approved'"); $rows=[]; foreach($providers as $p){ if(!gim_provider_bookable($p,$job->service_slug))continue; $coverage=gim_decode($p->coverage_json); if($coverage&&$job->postcode){ $prefix=strtoupper(substr(preg_replace('/\s+/','',$job->postcode),0,2)); $ok=false; foreach($coverage as $c){ if(str_starts_with(strtoupper(preg_replace('/\s+/','',$c)),$prefix)||str_starts_with($prefix,strtoupper(preg_replace('/\s+/','',$c)))){$ok=true;break;} } if(!$ok)continue; }
 $score=50; $oi=gim_latest_outcome($p->id,$job->service_slug); if($oi&&$oi->sample_size>=3){ $adj=max(-15,min(15,round(((float)$oi->outcome_score-50)*0.3))); $score+=$adj; }
 $rows[]=['provider'=>$p,'internal_score'=>$score,'outcome'=>$oi]; }
 usort($rows,fn($a,$b)=>$b['internal_score']<=>$a['internal_score']); gim_audit('matching.generated','job',$job->reference,['count'=>count($rows)]); return $rows; }
function gim_send_job_request($job_id,$provider_id,$customer_id){ global $wpdb; $job=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('jobs').' WHERE id=%d',$job_id)); if(!$job||!gim_job_owned_by_customer($job,$customer_id)||$job->vji_status!=='verified')return new WP_Error('forbidden','Invalid job.'); $p=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('providers').' WHERE id=%d',$provider_id)); if(!gim_provider_bookable($p,$job->service_slug))return new WP_Error('provider','Provider unavailable.'); $wpdb->replace(gim_table('job_requests'),['job_id'=>$job_id,'provider_id'=>$provider_id,'status'=>'sent','created_at'=>gim_now()]); $wpdb->update(gim_table('jobs'),['provider_id'=>$provider_id,'status'=>'provider_requested','updated_at'=>gim_now()],['id'=>$job_id]); gim_audit('job.provider_requested','job',$job->reference,['provider'=>$p->public_id]); return true; }
function gim_provider_respond_job($job_id,$provider_user_id,$decision){ global $wpdb; $p=gim_provider_profile($provider_user_id); if(!$p)return new WP_Error('provider','Provider not found.'); $job=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('jobs').' WHERE id=%d',$job_id)); if(!$job||(int)$job->provider_id!==(int)$p->id)return new WP_Error('forbidden','Not your job.'); if(!in_array($decision,['accept','decline'],true))return new WP_Error('decision','Invalid decision.'); $wpdb->update(gim_table('job_requests'),['status'=>$decision==='accept'?'accepted':'declined','responded_at'=>gim_now()],['job_id'=>$job_id,'provider_id'=>$p->id]); if($decision==='accept')$wpdb->update(gim_table('jobs'),['status'=>'provider_accepted','updated_at'=>gim_now()],['id'=>$job_id]); else $wpdb->update(gim_table('jobs'),['provider_id'=>null,'status'=>'verified_intent','updated_at'=>gim_now()],['id'=>$job_id]); gim_audit('job.provider_'.$decision,'job',$job->reference); return true; }
